// Add finite duration to the seek-less WebM container generated by MediaRecorder.
function header(bytes, at) {
  const vint = (pos, id = false) => {
    const first = bytes[pos];
    if (!first) throw Error('Header WebM terpotong.');
    let width = 1,
      mask = 128;
    while (!(first & mask)) {
      width++;
      mask >>= 1;
      if (width > 8) throw Error('Ukuran WebM tidak valid.');
    }
    if (pos + width > bytes.length) throw Error('Header WebM terpotong.');
    let n = BigInt(id ? first : first & (mask - 1));
    for (let i = 1; i < width; i++) n = (n << 8n) | BigInt(bytes[pos + i]);
    const unknown = !id && n === (1n << BigInt(width * 7)) - 1n;
    if (!unknown && n > BigInt(Number.MAX_SAFE_INTEGER)) throw Error('WebM terlalu besar.');
    return { width, value: unknown ? null : Number(n) };
  };
  const id = vint(at, true),
    size = vint(at + id.width);
  return {
    id: id.value,
    at,
    sizeAt: at + id.width,
    sizeWidth: size.width,
    size: size.value,
    data: at + id.width + size.width,
  };
}
function sizeBytes(n, width) {
  while (BigInt(n) >= (1n << BigInt(width * 7)) - 1n) width++;
  if (width > 8) throw Error('WebM terlalu besar.');
  const out = new Uint8Array(width);
  let value = BigInt(n) | (1n << BigInt(width * 7));
  for (let i = width - 1; i >= 0; i--) {
    out[i] = Number(value & 255n);
    value >>= 8n;
  }
  return out;
}
export function fixWebmDuration(input, seconds) {
  const bytes = input instanceof Uint8Array ? input : new Uint8Array(input);
  if (!Number.isFinite(seconds) || seconds <= 0 || seconds > 120 || bytes.length > 128 * 1024 ** 2)
    throw Error('Durasi WebM tidak valid.');
  let segment,
    at = 0;
  for (let i = 0; i < 16 && at < bytes.length; i++) {
    const h = header(bytes, at);
    if (h.id === 0x18538067) {
      segment = h;
      break;
    }
    if (h.size === null) break;
    at = h.data + h.size;
  }
  if (!segment) throw Error('Segment WebM tidak ditemukan.');
  let info;
  at = segment.data;
  for (let i = 0; i < 64 && at < bytes.length; i++) {
    const h = header(bytes, at);
    if (h.id === 0x114d9b74) throw Error('WebM dengan indeks seek tidak didukung.');
    if (h.id === 0x1549a966) {
      info = h;
      break;
    }
    if (h.size === null) break;
    at = h.data + h.size;
  }
  if (!info || info.size === null || info.data + info.size > bytes.length)
    throw Error('Info WebM tidak lengkap.');
  let scale = 1000000,
    duration;
  at = info.data;
  while (at < info.data + info.size) {
    const h = header(bytes, at);
    if (h.size === null || h.data + h.size > info.data + info.size)
      throw Error('Info WebM terpotong.');
    if (h.id === 0x2ad7b1) {
      scale = 0;
      for (let i = 0; i < h.size; i++) scale = scale * 256 + bytes[h.data + i];
    }
    if (h.id === 0x4489) duration = h;
    at = h.data + h.size;
  }
  if (!(scale > 0 && Number.isSafeInteger(scale))) throw Error('Skala waktu WebM tidak valid.');
  const ticks = (seconds * 1e9) / scale;
  if (duration) {
    const out = bytes.slice(),
      v = new DataView(out.buffer);
    if (duration.size === 8) v.setFloat64(duration.data, ticks, false);
    else if (duration.size === 4) v.setFloat32(duration.data, ticks, false);
    else throw Error('Durasi WebM tidak valid.');
    return out;
  }
  const field = new Uint8Array(11);
  field.set([0x44, 0x89, 0x88]);
  new DataView(field.buffer).setFloat64(3, ticks, false);
  const newInfoSize = sizeBytes(info.size + field.length, info.sizeWidth),
    delta = field.length + newInfoSize.length - info.sizeWidth;
  const segSize =
    segment.size === null
      ? bytes.slice(segment.sizeAt, segment.data)
      : sizeBytes(segment.size + delta, segment.sizeWidth);
  const pieces = [
    bytes.slice(0, segment.sizeAt),
    segSize,
    bytes.slice(segment.data, info.sizeAt),
    newInfoSize,
    bytes.slice(info.data, info.data + info.size),
    field,
    bytes.slice(info.data + info.size),
  ];
  const out = new Uint8Array(pieces.reduce((n, p) => n + p.length, 0));
  let pos = 0;
  for (const p of pieces) {
    out.set(p, pos);
    pos += p.length;
  }
  return out;
}
